-- Static Pages CMS: admin-managed category/listing pages with SEO text and FAQs

CREATE TABLE IF NOT EXISTS static_pages (
  id               UUID         DEFAULT gen_random_uuid() PRIMARY KEY,
  title            TEXT         NOT NULL,
  slug             TEXT         NOT NULL UNIQUE,
  page_type        TEXT         NOT NULL DEFAULT 'cars'
                                CHECK (page_type IN ('cars', 'bikes', 'scooters', 'mixed')),
  meta_title       TEXT,
  meta_description TEXT,
  hero_heading     TEXT         NOT NULL,
  hero_subtext     TEXT,
  vehicles         JSONB        NOT NULL DEFAULT '[]',
  seo_heading      TEXT,
  seo_text         TEXT         NOT NULL DEFAULT '',
  faqs             JSONB        NOT NULL DEFAULT '[]',
  is_published     BOOLEAN      DEFAULT true,
  sort_order       INTEGER      DEFAULT 0,
  created_at       TIMESTAMPTZ  DEFAULT NOW(),
  updated_at       TIMESTAMPTZ  DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_static_pages_slug      ON static_pages(slug);
CREATE INDEX IF NOT EXISTS idx_static_pages_type      ON static_pages(page_type);
CREATE INDEX IF NOT EXISTS idx_static_pages_published ON static_pages(is_published);

CREATE OR REPLACE FUNCTION update_static_pages_updated_at()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN NEW.updated_at = NOW(); RETURN NEW; END; $$;

DROP TRIGGER IF EXISTS static_pages_updated_at ON static_pages;
CREATE TRIGGER static_pages_updated_at
  BEFORE UPDATE ON static_pages
  FOR EACH ROW EXECUTE FUNCTION update_static_pages_updated_at();

ALTER TABLE static_pages ENABLE ROW LEVEL SECURITY;

CREATE POLICY "public_read_static_pages"  ON static_pages FOR SELECT USING (is_published = true);
CREATE POLICY "service_all_static_pages"  ON static_pages FOR ALL    USING (auth.role() = 'service_role');

